<script>
(function(){$('[data-cash-lookup]').each(function(){var input=$(this),side=input.attr('data-cash-lookup'),hidden=$('#'+side+'-id');input.autocomplete({minLength:0,delay:250,source:function(req,res){$.getJSON('/admin/finance/cash_bank_transfer/lookup/cash_account',{term:req.term}).done(res).fail(function(){res([]);});},select:function(e,item){hidden.val(item.item.id);input.val(item.item.label);return false;},change:function(e,item){if(!item.item)hidden.val('');}}).on('focus',function(){if(input.val()==='')input.autocomplete('search','');}).on('input',function(){hidden.val('');});});})();
</script>
